import 'dart:convert';
import 'dart:typed_data';

/// Pre-cached in-memory bytes for Ai NoteZilla screenshots, banner and logo
class AiNoteZillaBytes {
  static final Map<String, Uint8List> _cache = {};

  static Uint8List? getBytes(String assetPath) {
    if (_cache.containsKey(assetPath)) return _cache[assetPath];
    final base64Str = _data[assetPath];
    if (base64Str == null) return null;
    final bytes = base64Decode(base64Str);
    _cache[assetPath] = bytes;
    return bytes;
  }

  static final Map<String, String> _data = {
    'assets/images/ai_notezilla_card_banner.png':
        '',
    'assets/images/ai_notezilla_logo.png':
        '',
  };
}
